// ---- material choice ------------------------------------------------------------------------------------------------
const LIGHT_LETTERS = ["gold_block", "smooth_quartz", "white_concrete", "yellow_concrete"], DARK_LETTERS = ["black_concrete", "polished_blackstone", "dark_oak_planks", "deepslate_tiles"];
/** Letters that read on a board: the requested block if legible, else the best of the light (dark board) or dark set. */
export function chooseLetter(board, requested, notes = []) {
  if (requested && legible(requested, board)) return requested;
  const dark = (lumOf(board) ?? 128) < 110, pool = dark ? LIGHT_LETTERS : DARK_LETTERS;
  const pick = pool.find((b) => legible(b, board)) ?? pool[0];
  if (requested) notes.push(`plaque: ${requested} letters would not read on ${board} (contrast under 35%): used ${pick}`);
  return pick;
}

/**
 * A plaque: lettering centred in a band, the letter style chosen by the space. Styles tried in order (style: "auto"):
 *   block    5-row font, wide then narrow glyphs, one line then two, on a board with a 1-cell margin and a frame ring
 *            (frame and margin are dropped first when the band is short); a drip cap of stairs over the frame
 *   banner   one banner letter per character hung on a 2-row board (bands 2-4 rows tall, or too narrow for blocks)
 *   sign     wall signs across a 1-row band
 * material: the board (null keeps the wall as the board); letter: the letter block (checked for contrast); frame:
 * the ring block (null: none). relief "raised" puts the letters one block proud of the board instead of flush.
 * plan.info.style tells which style was used.
 */
export function plaquePlan(text, { at, face, width, height, letter, material = "dark_oak_planks", frame: frameBlock = "stripped_spruce_wood", style = "auto", relief = "flush", cap = true, look = LOOK_NONE, wall, dataVersion = 4189 } = {}) {
  const F = frame(face, at), writes = [], notes = [], T = String(text ?? "").toUpperCase().replace(/\s+/g, " ").trim();
  if (!T) return { writes, notes: ["plaque: no text (write the words in quotes)"], info: { style: "none" } };
  const W = width, H = height, board = material || wall || "stone_bricks";
  const tryBlock = () => {
    for (const lines of [[T], wrap2(T)].filter(Boolean)) for (const [pad, fr] of [[1, 1], [1, 0], [0, 0]]) for (const font of ["wide", "narrow"]) {
      const lw = Math.max(...lines.map((l) => textWidth(l, font))), th = lines.length * 5 + (lines.length - 1);
      {
        if (fr && !frameBlock) continue;
        if (!material && pad && !fr) continue;                             // no board and no frame: margin is meaningless
        const bw = lw + 2 * pad + 2 * fr, bh = th + 2 * pad + 2 * fr;
        if (bw <= W && bh <= H) return { lines, font, pad, fr, bw, bh, lw, th };
      }
    }
    return null;
  };
  const S = style === "auto" || style === "block" ? tryBlock() : null;
  if (S) {
    const ink = chooseLetter(board, letter, notes);
    const u0 = Math.floor((W - S.bw) / 2), v0 = Math.floor((H - S.bh) / 2);
    const ink2 = new Set();
    S.lines.forEach((line, li) => {
      const L = layoutText(line, S.font), x0 = u0 + S.fr + S.pad + Math.floor((S.lw - L.width) / 2);
      const y0 = v0 + S.fr + S.pad + (S.lines.length - 1 - li) * 6;
      for (const c of L.cells) ink2.add(`${x0 + c.x},${y0 + c.y}`);
    });
    for (let u = u0; u < u0 + S.bw; u++) for (let v = v0; v < v0 + S.bh; v++) {
      const ring = S.fr && (u === u0 || v === v0 || u === u0 + S.bw - 1 || v === v0 + S.bh - 1);
      if (ring) { writes.push(block(F.p(u, v), frameBlock, "recolor", /_(log|wood)$/.test(frameBlock) ? { state: { axis: u === u0 || u === u0 + S.bw - 1 ? "y" : F.right[0] ? "x" : "z" } } : {})); continue; }
      const isInk = ink2.has(`${u},${v}`);
      if (isInk && relief === "raised") { if (material) writes.push(block(F.p(u, v), material, "recolor")); writes.push(block(F.p(u, v, 1), ink, "air")); }
      else if (isInk) writes.push(block(F.p(u, v), ink, "recolor"));
      else if (material) writes.push(block(F.p(u, v), material, "recolor"));
    }
    if (cap && S.fr) for (let u = u0; u < u0 + S.bw; u++) writes.push(stair(F.p(u, v0 + S.bh - 1, 1), frameMat(frameBlock), F.outName, "top", "soft"));
    return { writes, notes, info: { style: "block", font: S.font, lines: S.lines, letter: ink, board: { u0, v0, w: S.bw, h: S.bh } } };
  }
  const chars = [...T];
  if ((style === "auto" || style === "banner") && H >= 2 && W >= chars.length) {
    const ink = chooseLetter(board, letter, notes), baseDye = dyeOf(board) === dyeOf(ink) ? ((lumOf(ink) ?? 128) > 110 ? "black" : "white") : dyeOf(board);
    let inkDye = dyeOf(ink);
    if (inkDye === baseDye) inkDye = baseDye === "black" ? "white" : "black";
    const bw = Math.min(W, chars.length + 2), u0 = Math.floor((W - bw) / 2), v0 = Math.floor((H - 2) / 2), x0 = u0 + Math.floor((bw - chars.length) / 2);
    for (let u = u0; u < u0 + bw; u++) for (let v = v0; v < v0 + 2; v++) writes.push(block(F.p(u, v), board, "recolor"));
    chars.forEach((ch, i) => {
      const pats = bannerLetter(ch, inkDye, baseDye);
      if (!pats) return;                                                  // a space: the board shows
      writes.push(block(F.p(x0 + i, v0 + 1, 1), `${baseDye}_wall_banner`, "rail", { state: { facing: F.outName }, nbt: bannerNbt(pats), support: F.p(x0 + i, v0 + 1) }));
    });
