  const out = { placed: 0, skipped: [], box: boxOf(cells) };
  for (const [x, y, z, [block, state, nbt]] of cells) {
    if (g.inBounds(x, y, z) && (over || g.isAir(x, y, z))) { g.set(x, y, z, block, state, nbt); out.placed++; }
    else out.skipped.push([x, y, z, block]);
